package com.nelja.urqr.audit;
import io.swagger.v3.oas.annotations.security.SecurityRequirement;
import com.nelja.urqr.security.CurrentTenant;import java.time.Instant;import java.util.UUID;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/audit") @PreAuthorize("hasRole('MANAGER')") @SecurityRequirement(name="bearerAuth")
public class AuditController{private final AuditRecordRepository audit;private final CurrentTenant tenant;public AuditController(AuditRecordRepository a,CurrentTenant t){audit=a;tenant=t;}@GetMapping public Page<AuditDto> list(@AuthenticationPrincipal Jwt jwt,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){var pageable=PageRequest.of(p.getPageNumber(),Math.max(1,Math.min(p.getPageSize(),100)),p.getSort());return audit.findAllByHotelIdOrderByCreatedAtDesc(tenant.hotelId(jwt),pageable).map(AuditDto::from);}public record AuditDto(UUID id,UUID userId,String action,String entity,String entityId,String oldValue,String newValue,Instant createdAt){static AuditDto from(AuditRecord a){return new AuditDto(a.getId(),a.getUserId(),a.getAction(),a.getEntity(),a.getEntityId(),a.getOldValue(),a.getNewValue(),a.getCreatedAt());}}}
